INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('955a5113-abc9-5a17-be90-6c221999f9f2','TEXT','The Tiny Ferry','Ruby liked helping at the river workshop, especially when there was a small job that nobody had planned. One Tuesday, Ruby noticed the model ferry was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Ruby decided to stop and look carefully instead of rushing.
