INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('5fc50f1d-2738-5340-9762-71194fbc8b8c','TEXT','The Orange Tree Calendar','Zoe liked helping at the school orchard, especially when there was a small job that nobody had planned. One Saturday, Zoe noticed the fruit calendar was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Zoe decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('83e4b2c4-86a1-5e84-839e-a86ee46627be','TEXT','The Creek Sound Map — A Different Day','Eli liked helping at the creek reserve, especially when there was a small job that nobody had planned. One Tuesday, Eli noticed the sound map was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Eli decided to stop and look carefully instead of rushing.
