INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('4c1ba5ec-185f-590c-a328-16b942c25416','TEXT','The Creek Sound Map','Eli liked helping at the creek reserve, especially when there was a small job that nobody had planned. One Tuesday, Eli noticed the sound map was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Eli decided to stop and look carefully instead of rushing.
