INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('794cd9d3-b5d1-5457-a3a5-afabc617a3e5','TEXT','The Repaired Book','Amara liked helping at the library corner, especially when there was a small job that nobody had planned. One Tuesday, Amara noticed the repair kit was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Amara decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('fb0619f3-f3d4-5b9c-9fb2-ed20ccaf71fd','TEXT','The Windy Sculpture — A Different Day','Kai liked helping at the community hall, especially when there was a small job that nobody had planned. One Friday, Kai noticed the reed sculpture was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Kai decided to stop and look carefully instead of rushing.
