INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('2229a1fe-716d-53ff-afdd-74eaae0af7e0','TEXT','The Seed Library','Arun liked helping at the community garden, especially when there was a small job that nobody had planned. One Saturday, Arun noticed the seed envelopes was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Arun decided to stop and look carefully instead of rushing.
